{
  "contract": "X7RLiquidityHub",
  "closure": {
    "site_function": "sendTreasuryBalance",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "processFees",
      "sendDistributeBalance",
      "sendTreasuryBalance"
    ],
    "justification": "Includes all functions that can be called during the risky site and affect the exposed storage."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "processFees",
      "sendDistributeBalance"
    ],
    "nesting_bound": {
      "sendTreasuryBalance": 1
    }
  },
  "phases": {
    "function": "sendTreasuryBalance",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "distributeBalance + treasuryBalance + liquidityBalance + inFlight <= _ethBal",
    "stable_formula": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of balances plus any in-flight amount does not exceed the ETH balance, maintaining the target property."
  }
}
